import io
from rich.console import Console
from rich.file_proxy import FileProxy

class MockFile:
    def isatty(self):
        return True
    def write(self, s):
        pass
    def flush(self):
        pass
    def fileno(self):
        return 1

def test_isatty_proxy():
    console = Console()
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)

    # CLAIM: FileProxy should proxy isatty() to the wrapped file
    # Currently FileProxy inherits from io.TextIOBase, which provides isatty() returning False.
    # Because isatty is defined in the base class, __getattr__ is not called.
    assert proxy.isatty() is True, f"Expected True, got {proxy.isatty()}"

if __name__ == "__main__":
    test_isatty_proxy()
